WITH RecentOrders AS (SELECT *, CASE WHEN discount >= 0.41 THEN 'High' WHEN discount >= 0.15 THEN 'Medium' ELSE 'Low' END AS discount_level FROM orders WHERE status = 'RETURNED' AND status <> 'SHIPPED'), summary AS (SELECT channel, MIN(order_date) AS first_order_date FROM RecentOrders GROUP BY channel) SELECT channel, first_order_date FROM summary ORDER BY first_order_date, channel;
